from aiogram.types import InlineKeyboardButton,InlineKeyboardMarkup
def menu(): return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text='🎵 TikTok',callback_data='video:tiktok'),InlineKeyboardButton(text='▶️ YouTube',callback_data='video:youtube')],[InlineKeyboardButton(text='📘 Facebook',callback_data='video:facebook'),InlineKeyboardButton(text='📸 Instagram',callback_data='video:instagram')],[InlineKeyboardButton(text='⬅️ Back',callback_data='nav:back'),InlineKeyboardButton(text='🏠 Main Menu',callback_data='nav:home')]])
def platform(p): return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text='🔗 Send URL',callback_data=f'video:input:{p}')],[InlineKeyboardButton(text='⬅️ Back',callback_data='nav:back'),InlineKeyboardButton(text='🏠 Main Menu',callback_data='nav:home')]])
def result(p): return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text='🌟 HD',callback_data=f'video:mock:{p}:hd'),InlineKeyboardButton(text='⚡ Normal',callback_data=f'video:mock:{p}:normal')],[InlineKeyboardButton(text='⬅️ Back',callback_data='nav:back'),InlineKeyboardButton(text='🏠 Main Menu',callback_data='nav:home')]])
